def pagehead(c,sub,title,w,h):
    rect(c,0,0,w,h,PAPER);rect(c,0,h-6,w,6,INK);txt(c,23,h-24,'МОРЕ ИМЁН   /   '+sub.upper(),8,'SB',MUTED);txt(c,22,h-53,title,23,'GB');stroke(c,LINE);c.line(23,h-65,w-23,h-65)

def fieldpage(c,index):
    w,h=landscape(A4);c.setPageSize((w,h));title,zones,links=fields[index];pagehead(c,'Тактический лист 0'+str(index+1),title,w,h);tag=['Переправа, деревня Три Ивы','Глубины I–V, сменные опасности','Удержать ворота четыре раунда'][index];txt(c,w-23,h-46,tag,10,'G',MUTED,'right')
    poss=[[(.13,.72),(.41,.72),(.71,.70),(.46,.30),(.16,.28),(.78,.30)],[(.12,.52),(.31,.52),(.50,.77),(.50,.29),(.71,.52),(.89,.52)],[(.15,.53),(.46,.53),(.29,.78),(.29,.27),(.72,.76),(.81,.30)]][index];xx,yy,ww,hh=22,92,w-44,h-174
    rect(c,xx,yy,ww,hh,['#e7e5c6','#dfe4d8','#e9dfc6'][index]);rng=random.Random(index+381)
    for step in range(26):
        col=['#d2d6b5','#cad3c3','#d9ceb5'][index];stroke(c,col);c.setLineWidth(.6);p=c.beginPath();y=yy+8+step*hh/26;p.moveTo(xx,y)
        for j in range(1,51):p.lineTo(xx+j*ww/50,min(yy+hh,max(yy+1,y+math.sin(j*.33+step*.37)*5+rng.random()*4)))
        c.drawPath(p)
    pts=[(xx+x*ww,yy+y*hh) for x,y in poss];
    for a,b in links:
        ax,ay=pts[a-1];bx,by=pts[b-1];stroke(c,'#a69e80');c.setLineWidth(12);c.line(ax,ay,bx,by);stroke(c,'#f6edcf');c.setLineWidth(8);c.line(ax,ay,bx,by);stroke(c,'#938969');c.setLineWidth(.7);c.setDash(4,3);c.line(ax,ay,bx,by);c.setDash()
    for j,(x,y) in enumerate(pts):
        stroke(c,'#697969');clr(c,'#f8f2db');c.setLineWidth(1.1);c.roundRect(x-43,y-26,86,52,10,stroke=1,fill=1);clr(c,INK);c.circle(x,y+25,9,stroke=0,fill=1);txt(c,x,y+22,str(j+1),7.5,'SB',PAPER,'center');txt(c,x,y-16,zones[j],9,'SB',INK,'center')
    comments=[('Задача','Успеть до конца третьего раунда. Старт героев: 1. Лада: 3. Стража: 4.'),('Задача','Улика в 3; ключевой затвор в 6. Дверь 5–6 заперта до рычага или проверки.'),('Задача','Отряд в 1–4. Волны в 5 и 6 в раундах 1 и 3. Ворота: 3 + число героев.')][index];txt(c,24,65,comments[0].upper(),8,'SB',GOLD);txt(c,24,46,comments[1],11,'G');txt(c,24,18,'Внутри рамок можно ставить фигурки и жетоны. Линия = один шаг. Рамка = одна зона.',8,'S',MUTED);c.showPage()

