    panel(23,88,66*mm,90*mm,'Герой H____','место для карты 63 × 88 мм');panel(23,355,66*mm,137,'Сердца: _____ / _____','Пишите максимум при росте. 1 крупное = 5.');panel(224,355,136,137,'Искры: ____ / ____','В начале сцены заполнить.');panel(368,355,150,137,'Зелья  /  пояс','Два места; выпить — действие.');panel(526,355,w-549,137,'Казна и припасы','Общие: эскиз или запись в журнале.');
