    panel(620,87,190,122,'Рюкзак','Запас: три предмета.');txt(c,636,133,'I_____   I_____   I_____',12,'G');txt(c,24,51,'Один шаг + одно действие   •   Бросок: 2d6 + М / Л / В + ступень − 1   •   Защита героя: 9',12,'SB');txt(c,24,25,'Снаряжение вне боя меняется свободно. Число на фишке здоровья обозначает номинал, контурное сердце — максимум.',8,'S',MUTED);c.showPage()

