start=[('h','Зачитайте за столом'),('p','Никто в Трёх Ивах не боится наводнений. Здесь дети учатся плавать раньше, чем ходить. Сегодня берег сух, но лодочник кричит: «Чья это девочка?» Девочка держит за руку свою мать. Та не отвечает. В звоннице сама по себе натягивается верёвка.'),('h','Подготовка за пять минут'),('p','Возьмите по одному герою с листа 3; ведущий необязателен. Один игрок с ведущим берёт двоих. Поставьте героев в 1, Ладу в 3, M001 в 4: для 2/3/4/5/6 героев нужно 1/2/2/3/3 фигуры. У героев 8 ОЗ, 3 искры и по зелью I19. Запишите дубликаты вещей на планшетах. В этот вечер хватит карандаша, двух d6 и монет.'),('h','Первая реплика ведущего'),('p','«Лада не отпускает верёвку. Что вы делаете?» Свободные вопросы и разговор ничего не стоят. Когда кто-то тронет верёвку или войдёт на отмель, начинается раунд 1. Дайте всем шаг и действие, затем действует стража. В конце третьего раунда решается судьба переправы.'),('h','Три выхода'),('p','В 3 потратьте два успешных действия (Мощь или Воля против 7) на коромысло; либо победите стражу и действием в 4 снимите язык; либо в 3 отдайте Ладе флакон и успешно спойте с ней (Воля 8, успех с ценой вне боя, в бою нужен полный успех). При успехе отметьте 1 опыт, N+1 серебра, след арки 01 и +1 слава Вельна. Коромысло или песня: голос улицы. Снятый язык: улика «медь». При опоздании улика-крошка остаётся, +1 прилив и следующая глава всё равно открыта.'),('h','После сцены'),('p','Попросите каждого назвать одну деталь, которую герой помнит лучше лодочника. Хотите дальше — прочтите главу II в атласе. Хотите закончить сегодня — Лада гравирует ваши имена на языке, пока звонница ещё узнаёт их.')]
quick=[('h','На своём ходу'),('p','1 шаг вдоль линии и 1 действие: ударить, применить личный приём за 1 искру, выпить или дать рядом зелье, помочь союзнику, поставить щит 2, пробежать ещё 1 зону либо работать с объектом. Можно действовать до шага. Помощь — преимущество союзнику рядом на один оговорённый бросок.'),('h','Два шестигранника'),('p','На уровне 1 бросьте 2d6 + Мощь (М), Ловкость (Л) или Воля (В). Не ниже порога — успех. При преимуществе бросьте три, оставьте лучшие две, при помехе — худшие. Любой до броска может потратить 1 искру на +1. Чистые 12 всегда успех и +1 искра; чистые 2 всегда провал.'),('h','Бой с гончей'),('p','Обычная атака: бросок характеристики оружия против защиты 8, при попадании оружие наносит 2. На первом листе вещей напечатаны характеристики и ограничения оружия ваших героев. Совпавшие номера оружия позволяют распечатать дополнительные экземпляры или записать их. Красный отвар I19 возвращает 3 ОЗ. Каждый враг шагает к ближайшему герою и, если достаёт, бросает 2d6 + 1 против защиты 9. При равенстве целей выбирает менее здорового, затем меньший ID. Щит поглощает урон и истощается. При 0 ОЗ вы лежите; сосед действием один раз за сцену возвращает 2 ОЗ, или союзник даёт вам зелье.'),('h','Значки на первых картах'),('p','Метка: следующий попавший удар героя по цели +1 урона, метка исчезает. Надлом: следующее попадание по носителю +1 урона, затем снять. Путы лишают бесплатного шага. Озноб даёт помеху следующей атаке. Толчок не даёт лишнего урона. Нерешённый спор: сначала текст карты, затем общие правила, в остальных ситуациях объявите порог и цену до броска.'),('h','Если играете без ведущего'),('p','Первый игрок читает сцену, затем каждый ведёт своего героя. Стража действует по инструкции. Не читайте наперёд, что случится в столице. Скрытый портал появляется только после следа и исследования; ставить арку сейчас не требуется.')]

def starter():
    c=Canvas(str(OUT/'00 Первый вечер.pdf'));c.setTitle('Первый вечер · Колокол у брода');bookpage(c,'Колокол у брода',start,1,'Первый вечер','ПРОЛОГ  /  2–6 ГЕРОЕВ  /  16+');bookpage(c,'Памятка первого боя',quick,2,'Первый вечер');sheet(c,['H01','H04','H07','H10','H13','H16','M001','M001','M001'],'ПРОЛОГ  /  ГЕРОИ И СТРАЖА');sheet(c,['I04','I01','I07','I03','I19','I19','I19','I19','I19'],'ПРОЛОГ  /  СНАРЯЖЕНИЕ');fieldpage(c,0);matpage(c);counters(c);c.save()

def gallery():
    gallery=OUT/'Галерея';gallery.mkdir(exist_ok=True);imout=OUT/'Карточки PNG';imout.mkdir(exist_ok=True);box=63*mm;bh=88*mm;sx=(A4[0]-3*box)/2;sy=(A4[1]-3*bh)/2
    for fn,pre in [('04 Герои','H'),('05 Существа','M'),('06 Боссы','B'),('07 Вещи','I')]:
        group=imout/fn[3:];group.mkdir(exist_ok=True);keys=[k for k in cards if k[0]==pre];doc=fitz.open(OUT/(fn+'.pdf'))
        for i,key in enumerate(keys):
            x=sx+(i%3)*box;y=sy+((i%9)//3)*bh;pix=doc[i//9].get_pixmap(matrix=fitz.Matrix(2,2),clip=fitz.Rect(x,y,x+box,y+bh),alpha=False);pix.save(group/(key+'.png'))
        doc.close()
    outimg=Image.new('RGB',(1550,850),'#eae3d0');dr=ImageDraw.Draw(outimg);from maps import font
    dr.text((46,32),'Море имён',font=font(57,True,True),fill=INK);dr.text((48,108),'ПЕЧАТНАЯ КОЛЛЕКЦИЯ     /     ГЕРОИ, СУЩЕСТВА И НАХОДКИ',font=font(20,True),fill=MUTED)
    for i,(group,key) in enumerate([('Герои','H07'),('Герои','H16'),('Существа','M001'),('Боссы','B086'),('Вещи','I14'),('Вещи','I20')]):
        pic=Image.open(imout/group/(key+'.png'));pic.thumbnail((239,360),Image.Resampling.LANCZOS);outimg.paste(pic,(43+i*245,166))
    dr.line([(46,528),(1500,528)],fill='#a3997d',width=2);dr.text((46,556),'Знаки на столе',font=font(29,True,True),fill=INK)
    for i,(kind,label,seed) in enumerate([('heart','Сердце',0),('spark','Искра',1),('helm','Шлем',2),('chest','Нагрудник',0),('boots','Обувь',1),('potion','Флакон',19),('sword','Оружие',3),('portal','Переправа',1)]):
        aa=icon(kind,seed).resize((132,132),Image.Resampling.NEAREST);x=64+i*186;outimg.paste(aa,(x,615),aa);dr.text((x+66,771),label,font=font(22,False,True),fill=INK,anchor='mm')
    outimg.save(gallery/'Карточки и знаки.png')

def main():
    worldmap();rules();campaign();decks();mapsbook();starter();gallery()
    data={'название':'Море имён','версия':'1.0, игровой прототип','карты':cards,'существа':MOBS,'боссы':BOSSES,'герои':heroes,'вещи':items,'королевства':realms,'дороги':edges};(OUT/'Каталог.json').write_text(json.dumps(data,ensure_ascii=False,indent=1),encoding='utf8');print('PDF и карточки:',len(cards),'кегль от',min(v for k,v in measure))
